#include <LiquidCrystal.h>

// ===============================
// LCD 1 - RFID STATUS
// RS, E, D4, D5, D6, D7
// ===============================
LiquidCrystal lcd1(13, 12, 11, 10, 9, 8);

// ===============================
// LCD 2 - REGISTRATION
// RS, E, D4, D5, D6, D7
// ===============================
LiquidCrystal lcd2(2, 3, A0, A1, A2, A3);

// ===============================
// OUTPUT PINS
// ===============================
int RedLED = 5;
int GreenLED = 6;
int Buzzer = 7;

// ===============================
// RFID CARD STORAGE
// ===============================
char card[30];
int count = 0;

// ===============================
// SETUP
// ===============================
void setup()
{
  Serial.begin(9600);

    pinMode(RedLED, OUTPUT);
      pinMode(GreenLED, OUTPUT);
        pinMode(Buzzer, OUTPUT);

          digitalWrite(RedLED, LOW);
            digitalWrite(GreenLED, LOW);
              digitalWrite(Buzzer, LOW);

                // LCD INITIALIZATION
                  lcd1.begin(20, 4);
                    lcd2.begin(20, 4);

                      // =============================
                        // LCD 1
                          // =============================
                            lcd1.clear();

                              lcd1.setCursor(0, 0);
                                lcd1.print("RFID SECURITY LOCK");

                                  lcd1.setCursor(0, 1);
                                    lcd1.print("ENTER CARD NUMBER");

                                      lcd1.setCursor(0, 2);
                                        lcd1.print("CARD:");

                                          lcd1.setCursor(0, 3);
                                            lcd1.print("NAME:");

                                              // =============================
                                                // LCD 2
                                                  // =============================
                                                    lcd2.clear();

                                                      lcd2.setCursor(0, 0);
                                                        lcd2.print("REG: 24BCE8046");

                                                          lcd2.setCursor(0, 1);
                                                            lcd2.print("U Hari Charan");

                                                              lcd2.setCursor(0, 3);
                                                                lcd2.print("RFID SYSTEM");

                                                                  // =============================
                                                                    // SERIAL TERMINAL
                                                                      // =============================
                                                                        Serial.println("================================");
                                                                          Serial.println("       RFID SECURITY LOCK");
                                                                            Serial.println("================================");
                                                                              Serial.println("Enter Card Number:");
                                                                                Serial.println("Press ENTER after typing");
                                                                                }

                                                                                // ===============================
                                                                                // LOOP
                                                                                // ===============================
                                                                                void loop()
                                                                                {
                                                                                  while (Serial.available() > 0)
                                                                                    {
                                                                                        char c = Serial.read();

                                                                                            // ENTER KEY
                                                                                                if (c == '\r' || c == '\n')
                                                                                                    {
                                                                                                          if (count > 0)
                                                                                                                {
                                                                                                                        card[count] = '\0';

                                                                                                                                checkCard();

                                                                                                                                        count = 0;
                                                                                                                                                card[0] = '\0';

                                                                                                                                                        Serial.println();
                                                                                                                                                                Serial.println("Enter Card Number:");
                                                                                                                                                                      }
                                                                                                                                                                          }

                                                                                                                                                                              // BACKSPACE
                                                                                                                                                                                  else if (c == 8)
                                                                                                                                                                                      {
                                                                                                                                                                                            if (count > 0)
                                                                                                                                                                                                  {
                                                                                                                                                                                                          count--;
                                                                                                                                                                                                                  card[count] = '\0';
                                                                                                                                                                                                                        }
                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                // NORMAL CHARACTER
                                                                                                                                                                                                                                    else
                                                                                                                                                                                                                                        {
                                                                                                                                                                                                                                              if (count < 29)
                                                                                                                                                                                                                                                    {
                                                                                                                                                                                                                                                            card[count] = c;
                                                                                                                                                                                                                                                                    count++;
                                                                                                                                                                                                                                                                            card[count] = '\0';
                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                        // ===============================
                                                                                                                                                                                                                                                                                        // CHECK CARD
                                                                                                                                                                                                                                                                                        // ===============================
                                                                                                                                                                                                                                                                                        void checkCard()
                                                                                                                                                                                                                                                                                        {
                                                                                                                                                                                                                                                                                          if (strcmp(card, "E280689401A9") == 0)
                                                                                                                                                                                                                                                                                            {
                                                                                                                                                                                                                                                                                                granted("ALTAF");
                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                    else if (strcmp(card, "E2000019060C") == 0)
                                                                                                                                                                                                                                                                                                      {
                                                                                                                                                                                                                                                                                                          granted("ZUBAIR");
                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                              else if (strcmp(card, "G46RD9V40F3") == 0)
                                                                                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                                                                                    granted("AMIR");
                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                        else if (strcmp(card, "B71001B76894") == 0)
                                                                                                                                                                                                                                                                                                                          {
                                                                                                                                                                                                                                                                                                                              granted("KHALID");
                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                  else if (strcmp(card, "1C81159073FD") == 0)
                                                                                                                                                                                                                                                                                                                                    {
                                                                                                                                                                                                                                                                                                                                        granted("IMRAN");
                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                            else if (strcmp(card, "B710D0186022") == 0)
                                                                                                                                                                                                                                                                                                                                              {
                                                                                                                                                                                                                                                                                                                                                  granted("MEHRAN");
                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                      else
                                                                                                                                                                                                                                                                                                                                                        {
                                                                                                                                                                                                                                                                                                                                                            denied();
                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                              // ===============================
                                                                                                                                                                                                                                                                                                                                                              // ACCESS GRANTED
                                                                                                                                                                                                                                                                                                                                                              // ===============================
                                                                                                                                                                                                                                                                                                                                                              void granted(const char *name)
                                                                                                                                                                                                                                                                                                                                                              {
                                                                                                                                                                                                                                                                                                                                                                digitalWrite(RedLED, LOW);
                                                                                                                                                                                                                                                                                                                                                                  digitalWrite(GreenLED, HIGH);
                                                                                                                                                                                                                                                                                                                                                                    digitalWrite(Buzzer, LOW);

                                                                                                                                                                                                                                                                                                                                                                      lcd1.clear();

                                                                                                                                                                                                                                                                                                                                                                        lcd1.setCursor(0, 0);
                                                                                                                                                                                                                                                                                                                                                                          lcd1.print("ACCESS GRANTED");

                                                                                                                                                                                                                                                                                                                                                                            lcd1.setCursor(0, 1);
                                                                                                                                                                                                                                                                                                                                                                              lcd1.print("CARD:");

                                                                                                                                                                                                                                                                                                                                                                                lcd1.setCursor(6, 1);
                                                                                                                                                                                                                                                                                                                                                                                  lcd1.print(card);

                                                                                                                                                                                                                                                                                                                                                                                    lcd1.setCursor(0, 2);
                                                                                                                                                                                                                                                                                                                                                                                      lcd1.print("NAME:");

                                                                                                                                                                                                                                                                                                                                                                                        lcd1.setCursor(6, 2);
                                                                                                                                                                                                                                                                                                                                                                                          lcd1.print(name);

                                                                                                                                                                                                                                                                                                                                                                                            lcd1.setCursor(0, 3);
                                                                                                                                                                                                                                                                                                                                                                                              lcd1.print("WELCOME!");

                                                                                                                                                                                                                                                                                                                                                                                                Serial.println("----------------------------");
                                                                                                                                                                                                                                                                                                                                                                                                  Serial.println("ACCESS GRANTED");
                                                                                                                                                                                                                                                                                                                                                                                                    Serial.print("CARD: ");
                                                                                                                                                                                                                                                                                                                                                                                                      Serial.println(card);
                                                                                                                                                                                                                                                                                                                                                                                                        Serial.print("NAME: ");
                                                                                                                                                                                                                                                                                                                                                                                                          Serial.println(name);
                                                                                                                                                                                                                                                                                                                                                                                                            Serial.println("----------------------------");
                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                            // ===============================
                                                                                                                                                                                                                                                                                                                                                                                                            // ACCESS DENIED
                                                                                                                                                                                                                                                                                                                                                                                                            // ===============================
                                                                                                                                                                                                                                                                                                                                                                                                            void denied()
                                                                                                                                                                                                                                                                                                                                                                                                            {
                                                                                                                                                                                                                                                                                                                                                                                                              digitalWrite(GreenLED, LOW);
                                                                                                                                                                                                                                                                                                                                                                                                                digitalWrite(RedLED, HIGH);

                                                                                                                                                                                                                                                                                                                                                                                                                  digitalWrite(Buzzer, HIGH);
                                                                                                                                                                                                                                                                                                                                                                                                                    delay(1000);
                                                                                                                                                                                                                                                                                                                                                                                                                      digitalWrite(Buzzer, LOW);

                                                                                                                                                                                                                                                                                                                                                                                                                        lcd1.clear();

                                                                                                                                                                                                                                                                                                                                                                                                                          lcd1.setCursor(0, 0);
                                                                                                                                                                                                                                                                                                                                                                                                                            lcd1.print("ACCESS DENIED");

                                                                                                                                                                                                                                                                                                                                                                                                                              lcd1.setCursor(0, 1);
                                                                                                                                                                                                                                                                                                                                                                                                                                lcd1.print("CARD:");

                                                                                                                                                                                                                                                                                                                                                                                                                                  lcd1.setCursor(0, 2);
                                                                                                                                                                                                                                                                                                                                                                                                                                    lcd1.print(card);

                                                                                                                                                                                                                                                                                                                                                                                                                                      lcd1.setCursor(0, 3);
                                                                                                                                                                                                                                                                                                                                                                                                                                        lcd1.print("INVALID CARD!");

                                                                                                                                                                                                                                                                                                                                                                                                                                          Serial.println("----------------------------");
                                                                                                                                                                                                                                                                                                                                                                                                                                            Serial.println("ACCESS DENIED");
                                                                                                                                                                                                                                                                                                                                                                                                                                              Serial.print("CARD: ");
                                                                                                                                                                                                                                                                                                                                                                                                                                                Serial.println(card);
                                                                                                                                                                                                                                                                                                                                                                                                                                                  Serial.println("INVALID CARD!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                    Serial.println("----------------------------");
                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                    ```

                                                                                                                                                                                                                                                                                                                                                                                                                                                    ### Exact wiring for this code

