                                                                                                                                                                                                                                                                                                                                                                                                                                                    VDD → 5V
                                                                                                                                                                                                                                                                                                                                                                                                                                                    VEE → Potentiometer middle pin
                                                                                                                                                                                                                                                                                                                                                                                                                                                    RS  → Arduino 13
                                                                                                                                                                                                                                                                                                                                                                                                                                                    RW  → GND
                                                                                                                                                                                                                                                                                                                                                                                                                                                    E   → Arduino 12
                                                                                                                                                                                                                                                                                                                                                                                                                                                    D4  → Arduino 11
                                                                                                                                                                                                                                                                                                                                                                                                                                                    D5  → Arduino 10
                                                                                                                                                                                                                                                                                                                                                                                                                                                    D6  → Arduino 9
                                                                                                                                                                                                                                                                                                                                                                                                                                                    D7  → Arduino 8
                                                                                                                                                                                                                                                                                                                                                                                                                                                    ```

                                                                                                                                                                                                                                                                                                                                                                                                                                                    **LCD 2 — LM044L**

                                                                                                                                                                                                                                                                                                                                                                                                                                                    ```text
                                                                                                                                                                                                                                                                                                                                                                                                                                                    VSS → GND
                                                                                                                                                                                                                                                                                                                                                                                                                                                    VDD → 5V
                                                                                                                                                                                                                                                                                                                                                                                                                                                    VEE → Potentiometer middle pin
                                                                                                                                                                                                                                                                                                                                                                                                                                                    RS  → Arduino 2
                                                                                                                                                                                                                                                                                                                                                                                                                                                    RW  → GND
                                                                                                                                                                                                                                                                                                                                                                                                                                                    E   → Arduino 3
                                                                                                                                                                                                                                                                                                                                                                                                                                                    D4  → Arduino A0
                                                                                                                                                                                                                                                                                                                                                                                                                                                    D5  → Arduino A1
                                                                                                                                                                                                                                                                                                                                                                                                                                                    D6  → Arduino A2
                                                                                                                                                                                                                                                                                                                                                                                                                                                    D7  → Arduino A3
                                                                                                                                                                                                                                                                                                                                                                                                                                                    ```

                                                                                                                                                                                                                                                                                                                                                                                                                                                    **LEDs + buzzer**

                                                                                                                                                                                                                                                                                                                                                                                                                                                    ```text
                                                                                                                                                                                                                                                                                                                                                                                                                                                    Red LED   → Arduino 5
                                                                                                                                                                                                                                                                                                                                                                                                                                                    Green LED → Arduino 6
                                                                                                                                                                                                                                                                                                                                                                                                                                                    Buzzer    → Arduino 7
                                                                                                                                                                                                                                                                                                                                                                                                                                                    ```

                                                                                                                                                                                                                                                                                                                                                                                                                                                    **Virtual Terminal**

                                                                                                                                                                                                                                                                                                                                                                                                                                                    ```text
