                                                                                                                                                                                                                                                                                                                                                                                                                                                    RXD → Arduino TX / pin 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                    ```

                                                                                                                                                                                                                                                                                                                                                                                                                                                    Set Virtual Terminal to:

                                                                                                                                                                                                                                                                                                                                                                                                                                                    ```text
