                                                                                                                                                                                                                                                                                                                                                                                                                                                    Data Bits: 8
                                                                                                                                                                                                                                                                                                                                                                                                                                                    Parity: None
                                                                                                                                                                                                                                                                                                                                                                                                                                                    Stop Bits: 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                    ```

                                                                                                                                                                                                                                                                                                                                                                                                                                                    Then type, for example:

                                                                                                                                                                                                                                                                                                                                                                                                                                                    ```text
